          "note": "Se reasigna tramite IPRUS no favorable, por favor continuar segun corresponda Observaciones 1. El trámite N.º 1177429 no es favorable en las condiciones presentadas. 2. El levantamiento planimétrico ingresado no refleja la realidad física del predio. 3. Se deberá realizar un nuevo levantamiento con equipos topográficos de precisión. 4. El levantamiento deberá ajustarse a los linderos, vértices y configuración real del predio. 5. No se deberá limitar el levantamiento a tratar de ajustar las medidas constantes en el certificado de gravamen.",
